insert into public.posts (kind, title, summary, category, source, date, href, position) values ('blog', '[KGU series 10] 득점왕의 탄생, 경기대의 새로운 심장, 유태호 선수', '2026년, 경기대학교 축구부의 전방에 새로운 활력을 불어넣은 ''무서운 신예''가 등장했습니다.', '인터뷰', '축구부 블로그', '2026-03-30', 'https://blog.naver.com/orangeturtles/224234051023', 2) on conflict (href) do nothing;
